import numpy as np
L=open('init.xyz').read().strip().split('\n')
n=int(L[0]); sy=[];P=[]
for l in L[2:2+n]:
    p=l.split(); sy.append(p[0]); P.append([float(x) for x in p[1:4]])
P=np.array(P)
def norm(v): return v/np.linalg.norm(v)
# find methyl groups: C with 3 H within 1.2 and one heavy neighbor
D=np.linalg.norm(P[:,None]-P[None],axis=-1)
groups=[]
for i,s in enumerate(sy):
    if s!='C': continue
    Hs=[j for j in range(n) if sy[j]=='H' and D[i,j]<1.2]
    hv=[j for j in range(n) if sy[j] in ('C','Si') and D[i,j]<2.1 and j!=i]
    if len(Hs)==3 and len(hv)==1: groups.append((i,hv[0],Hs))
print(len(groups))
def rot(pts,axis,origin,ang):
    a=norm(axis); c=np.cos(ang); s=np.sin(ang)
    K=np.array([[0,-a[2],a[1]],[a[2],0,-a[0]],[-a[1],a[0],0]])
    R=np.eye(3)*c+s*K+(1-c)*np.outer(a,a)
    return (pts-origin)@R.T+origin
for it in range(6):
    for ci,pi,Hs in groups:
        best=None
        others=[k for k in range(n) if k not in Hs and k!=ci]
        for ang in np.radians(np.arange(0,120,5)):
            newH=rot(P[Hs],P[ci]-P[pi],P[ci],ang)
            d=np.linalg.norm(newH[:,None]-P[others][None],axis=-1).min()
            if best is None or d>best[0]: best=(d,newH)
        P[Hs]=best[1]
D=np.linalg.norm(P[:,None]-P[None],axis=-1); np.fill_diagonal(D,99)
print('min dist',D.min())
for i,j in np.argwhere(D<1.3):
    if i<j and not (sy[i]=='H' or sy[j]=='H') or (i<j and D[i,j]<1.2 and sy[i]=='H' and sy[j]=='H'): print(i,sy[i],j,sy[j],round(D[i,j],2))
with open('init2.xyz','w') as f:
    f.write(f"{n}\nfixed\n")
    for s,p in zip(sy,P): f.write(f"{s} {p[0]:.4f} {p[1]:.4f} {p[2]:.4f}\n")
