import numpy as np
def norm(v): return v/np.linalg.norm(v)
dcp=2.07; rring=1.19
for halfd in [65,70,75]:
  for tilt in [0.15,0.3,0.45,0.6]:
    half=np.radians(halfd)
    pts=[]
    for sign in (1,-1):
        d=norm(np.array([-np.cos(half),0,sign*np.sin(half)])); cen=dcp*d
        e1=np.array([0,-1.,0]); e2=sign*np.cross(d,e1)
        for k in range(5):
            th=np.radians(72*k)
            C=cen+rring*(np.cos(th)*e1+np.sin(th)*e2)
            out=norm(norm(C-cen)+tilt*d)
            pts.append((sign,k,C,C+1.51*out))
    best=9
    for a in pts:
        for b in pts:
            if a[0]!=b[0]:
                best=min(best,np.linalg.norm(a[3]-b[3]))
    print(halfd,tilt,round(best,2))
